const WORKSHEET_1A = Object.freeze({
  2025: Object.freeze({
    // Line 1g (2020+ Form W-4, Step 2 box NOT checked)
    line1gMarriedFilingJointlyCents: 12_900_00,
    line1gOtherCents: 8_600_00,
    // Line 1k (2019-or-earlier Form W-4): per withholding allowance
    allowanceCents: 4_300_00,
    sources: Object.freeze([
      "IRS Publication 15-T (2025), Worksheet 1A and Percentage Method Tables for Automated Payroll Systems: https://www.irs.gov/pub/irs-prior/p15t--2025.pdf",
    ]),
  }),
  2026: Object.freeze({
    line1gMarriedFilingJointlyCents: 12_900_00,
    line1gOtherCents: 8_600_00,
    allowanceCents: 4_300_00,
    sources: Object.freeze([
      "IRS Publication 15-T (2026), Worksheet 1A and Percentage Method Tables for Automated Payroll Systems: https://www.irs.gov/publications/p15t",
    ]),
  }),
});

function deepFreeze(o) {
  Object.values(o).forEach((v) => typeof v === "object" && v !== null && deepFreeze(v));
  return Object.freeze(o);
}
deepFreeze(PERCENTAGE_METHOD_TABLES);

const FILING_STATUSES = ["single", "marriedFilingJointly", "headOfHousehold"];

/**
 * What an employee's Form W-4 says. Two shapes, matching the two forms:
 *
 * 2020 or later (formYear >= 2020):
 *   { formYear, filingStatus: "single" | "marriedFilingJointly" | "headOfHousehold",
 *     step2Checkbox?: boolean, step3CreditsCents?, step4aOtherIncomeCents?,
 *     step4bDeductionsCents?, step4cExtraWithholdingCents?, exempt?: boolean }
 *   ("Married filing separately" uses "single", as the IRS table does.)
 *
 * 2019 or earlier (formYear < 2020):
 *   { formYear, maritalStatus: "single" | "married", allowances,
 *     extraWithholdingCents?, exempt?: boolean }
 *   ("Married, but withhold at higher Single rate" uses "single".)
 *
 * No W-4 on file: pass null. Per IRS Publication 15 (2026), the employer
 * withholds as if the employee checked Single and made no other entries;
 * the result says so (w4Basis: "none-on-file").
 */
function validateW4(w4) {
  if (w4 === null || w4 === undefined) return;
  const fail = (m) => {
    throw new Error(`Form W-4: ${m}`);
  };
  if (!Number.isInteger(w4.formYear)) fail("formYear must be an integer year");
  const cents = (v, name) => {
    if (v !== undefined && v !== null && (!Number.isSafeInteger(v) || v < 0)) {
      fail(`${name} must be a non-negative integer number of cents`);
    }
  };
  if (w4.formYear >= 2020) {
    if (!FILING_STATUSES.includes(w4.filingStatus)) {
      fail(`filingStatus must be one of ${FILING_STATUSES.join(", ")}`);
    }
    cents(w4.step3CreditsCents, "step3CreditsCents");
    cents(w4.step4aOtherIncomeCents, "step4aOtherIncomeCents");
    cents(w4.step4bDeductionsCents, "step4bDeductionsCents");
    cents(w4.step4cExtraWithholdingCents, "step4cExtraWithholdingCents");
  } else {
    if (!["single", "married"].includes(w4.maritalStatus)) fail('maritalStatus must be "single" or "married"');
    if (!Number.isInteger(w4.allowances) || w4.allowances < 0) fail("allowances must be a non-negative integer");
    cents(w4.extraWithholdingCents, "extraWithholdingCents");
  }
}

function getWithholdingTables(taxYear) {
  const brackets = PERCENTAGE_METHOD_TABLES[taxYear];
  const worksheet = WORKSHEET_1A[taxYear];
  if (!brackets || !worksheet) {
    const known = Object.keys(PERCENTAGE_METHOD_TABLES).join(", ");
    throw new Error(
      `no sourced IRS withholding tables for tax year ${taxYear} (have: ${known}); ` +
        "add them from that year's Publication 15-T before running payroll for it"
    );
  }
  return { brackets, worksheet };
}

/** Annual tentative withholding from one schedule (Worksheet 1A, lines 2b-2g). */
function annualTentativeCents(schedule, adjustedAnnualWageCents) {
  let row = schedule[0];
  for (const r of schedule) if (adjustedAnnualWageCents >= r[0]) row = r;
  const [overCents, baseCents, rateBp] = row;
  return baseCents + ((adjustedAnnualWageCents - overCents) * rateBp) / 10_000;
}

/**
 * computeFederalWithholdingCents
 * --------------------------------
 * taxableWagesCents: this period's wages subject to federal income tax
 *   (gross pay minus pre-tax deductions such as traditional 401(k)
 *   deferrals) - Worksheet 1A line 1a.
 * payPeriodsPerYear: line 1b (52, 26, 24, 12, ...).
 *
 * Returns { federalCents, adjustedAnnualWageCents, w4Basis, lines } where
 * lines holds the worksheet lines, so anyone can check the arithmetic.
 */
function computeFederalWithholdingCents({ taxYear, taxableWagesCents, payPeriodsPerYear, w4 }) {
  const { brackets, worksheet } = getWithholdingTables(taxYear);
  if (!Number.isSafeInteger(taxableWagesCents) || taxableWagesCents < 0) {
    throw new Error("taxableWagesCents must be a non-negative integer");
  }
  if (!Number.isInteger(payPeriodsPerYear) || payPeriodsPerYear <= 0) {
    throw new Error("payPeriodsPerYear is required to annualize wages for withholding");
  }
  validateW4(w4);

  const onFile = w4 !== null && w4 !== undefined;
  if (onFile && w4.exempt) {
    return { federalCents: 0, adjustedAnnualWageCents: null, w4Basis: "exempt", lines: {} };
  }
  // No W-4: Single, no other entries (IRS Publication 15).
  const form = onFile ? w4 : { formYear: 2020, filingStatus: "single" };
  const modern = form.formYear >= 2020;

  const line1c = taxableWagesCents * payPeriodsPerYear;
  let adjusted;
  let lines;
  let schedule;

  if (modern) {
    const status = form.filingStatus;
    const checkbox = Boolean(form.step2Checkbox);
    const line1d = form.step4aOtherIncomeCents || 0;
    const line1e = line1c + line1d;
    const line1f = form.step4bDeductionsCents || 0;
    const line1g = checkbox
      ? 0
      : status === "marriedFilingJointly"
        ? worksheet.line1gMarriedFilingJointlyCents
        : worksheet.line1gOtherCents;
    const line1h = line1f + line1g;
    adjusted = Math.max(0, line1e - line1h);
    schedule = brackets[status][checkbox ? "step2Checkbox" : "standard"];
    lines = { line1c, line1d, line1e, line1f, line1g, line1h, line1i: adjusted };
  } else {
    const line1k = form.allowances * worksheet.allowanceCents;
    adjusted = Math.max(0, line1c - line1k);
    // 2019-or-earlier forms: married -> MFJ table, single -> single table,
    // standard schedules only, never head of household (Pub 15-T note).
    schedule = brackets[form.maritalStatus === "married" ? "marriedFilingJointly" : "single"].standard;
    lines = { line1c, line1j: form.allowances, line1k, line1l: adjusted };
  }

  const line2g = annualTentativeCents(schedule, adjusted);
  const line2h = line2g / payPeriodsPerYear;
  const line3a = modern ? form.step3CreditsCents || 0 : 0;
  const line3b = line3a / payPeriodsPerYear;
  const line3c = Math.max(0, line2h - line3b);
  const line4a = modern ? form.step4cExtraWithholdingCents || 0 : form.extraWithholdingCents || 0;
  const federalCents = Math.round(line3c + line4a);

  return {
    federalCents,
    adjustedAnnualWageCents: adjusted,
    w4Basis: onFile ? (modern ? "form-2020-or-later" : "form-2019-or-earlier") : "none-on-file",
    lines: { ...lines, line2g, line2h, line3a, line3b, line3c, line4a, line4b: federalCents },
  };
}

module.exports = {
  PERCENTAGE_METHOD_TABLES,
  WORKSHEET_1A,
  FILING_STATUSES,
  getWithholdingTables,
  validateW4,
  computeFederalWithholdingCents,
};
